export const ns = (name) => (name.includes(":") ? name : `minecraft:${name}`);
const key = (x, y, z) => `${x},${y},${z}`;

// Blocks the game keeps a block entity for: a structure without one shows a bed or a chest broken (owner's walk-through:
// "broken beds") in loaders that don't create it on paste, so every one is written with at least its id.
const BLOCK_ENTITY = [
  [/_bed$/, "bed"], [/^(minecraft:)?(trapped_)?chest$/, (b) => (/trapped/.test(b) ? "trapped_chest" : "chest")], [/ender_chest$/, "ender_chest"], [/barrel$/, "barrel"],
  [/shulker_box$/, "shulker_box"], [/(^|:)furnace$/, "furnace"], [/smoker$/, "smoker"], [/blast_furnace$/, "blast_furnace"], [/hopper$/, "hopper"],
  [/dropper$/, "dropper"], [/dispenser$/, "dispenser"], [/lectern$/, "lectern"], [/(^|_)bell$/, "bell"], [/campfire$/, "campfire"], [/decorated_pot$/, "decorated_pot"],
  [/brewing_stand$/, "brewing_stand"], [/enchanting_table$/, "enchanting_table"], [/(beehive|bee_nest)$/, "beehive"], [/chiseled_bookshelf$/, "chiseled_bookshelf"],
  [/jukebox$/, "jukebox"], [/crafter$/, "crafter"], [/(^|_)banner$/, "banner"], [/(^|_)(wall_)?sign$/, "sign"], [/hanging_sign$/, "hanging_sign"],
  [/(skull|head)$/, "skull"], [/comparator$/, "comparator"], [/daylight_detector$/, "daylight_detector"],
];
function blockEntityOf(block) {
  const b = String(block);
  for (const [re, id] of BLOCK_ENTITY) if (re.test(b)) return `minecraft:${typeof id === "function" ? id(b) : id}`;
  return null;
}
// state keys a block needs that builders leave out (the game fills a default, some loaders don't)
const DEFAULT_STATE = [[/_bed$/, { occupied: "false" }]];
function withDefaults(c) {
  for (const [re, def] of DEFAULT_STATE) if (re.test(c.block)) { const st = { ...def, ...(c.state ?? {}) }; return { ...c, state: st }; }
  return c;
}

export class Grid {
  /** @param {[number,number,number]} size */
  constructor(size, { dataVersion = DATA_VERSIONS["1.21.4"], entities = null } = {}) {
    this.size = [...size];
    this.dataVersion = dataVersion;
    this.entities = entities;                     // typed NBT list, passed through untouched
    /** @type {Map<string, {pos:number[], block:string, state?:Record<string,string>, nbt?:object}>} */
    this.cells = new Map();
  }

  inBounds(x, y, z) {
    return x >= 0 && y >= 0 && z >= 0 && x < this.size[0] && y < this.size[1] && z < this.size[2];
  }

  /** Set one block (state values become strings, as in NBT). Grows nothing: out of bounds throws. */
  set(x, y, z, block, state, nbt) {
    if (!this.inBounds(x, y, z)) throw new Error(`set out of bounds: ${x},${y},${z} (size ${this.size})`);
    const s = state && Object.keys(state).length
      ? Object.fromEntries(Object.entries(state).map(([k, v]) => [k, String(v)])) : undefined;
    this.cells.set(key(x, y, z), { pos: [x, y, z], block: ns(block), ...(s ? { state: s } : {}), ...(nbt ? { nbt } : {}) });
    return this;
  }

  get(x, y, z) { return this.cells.get(key(x, y, z)); }
  blockAt(x, y, z) { return this.get(x, y, z)?.block ?? "minecraft:air"; }
  isAir(x, y, z) { return AIRS.has(this.blockAt(x, y, z)); }
  unset(x, y, z) { this.cells.delete(key(x, y, z)); return this; }

  /** Fill the inclusive box a..b. */
  fill(a, b, block, state) {
    for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
      for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
        for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) this.set(x, y, z, block, state);
    return this;
  }

  *[Symbol.iterator]() { yield* this.cells.values(); }

  /** Non-air cells. */
  solids() { return [...this.cells.values()].filter((c) => !AIRS.has(c.block)); }

  clone() {

